Given, $\gamma=\frac{5}{3}$
\frac{\mathrm{C}_{\mathrm{p}}}{\mathrm{C}_{\mathrm{v}}}=\frac{5}{3}

Percentage of heat energy needed to increase the internal energy

\begin{aligned}
& =\frac{\Delta U}{Q} \times 100=\frac{\mathrm{nC}_{\mathrm{v}} \Delta \mathrm{T}}{\mathrm{nCp} \cdot \mathrm{dT}} \times 100 \\
& =\frac{\mathrm{C}_{\mathrm{v}}}{\mathrm{C}_{\mathrm{p}}} \times 100=\frac{3}{5} \times 100 \\
& =60 \%
\end{aligned}

Here process is isothermal

So, $p \propto \frac{1}{V}$
for containers, A

\begin{aligned}
& 2 \Delta \mathrm{P}=\left(\mathrm{P}_{\mathrm{A}}\right)_{\mathrm{j}}-\left(\mathrm{P}_{\mathrm{A}}\right)_{\mathrm{f}} \\
& =\frac{\mathrm{n}_{\mathrm{A}} \mathrm{RT}}{\mathrm{V}}-\frac{\mathrm{n}_{\mathrm{A}} \mathrm{RT}}{2 \mathrm{~V}}
\end{aligned}

$2 \Delta \mathrm{P}=\frac{\mathrm{n}_{\mathrm{A}} \mathrm{RT}}{2 \mathrm{~V}}$ ...(1)
For containers, B

\begin{aligned}
& 3 \Delta \mathrm{P}=\left(\mathrm{P}_{\mathrm{B}}\right)_{\mathrm{j}}-\left(\mathrm{P}_{\mathrm{B}}\right)_{\mathrm{f}} \\
& 3 \Delta \mathrm{P}=\frac{\mathrm{n}_{\mathrm{B}} \mathrm{RT}}{\mathrm{V}}-\frac{\mathrm{n}_{\mathrm{B}} \mathrm{RT}}{2 \mathrm{~V}}
\end{aligned}

$3 \Delta \mathrm{P}=\frac{2 \mathrm{n}_{\mathrm{B}} \mathrm{RT}}{2 \mathrm{~V}}$ ...(3)
Divide equation (1) by (2), we have

\begin{aligned}
& \frac{2 \Delta \mathrm{P}}{3 \Delta \mathrm{P}}=\frac{\mathrm{n}_{\mathrm{A}} \mathrm{RT}}{2 \mathrm{~V}} \times \frac{2 \mathrm{~V}}{\mathrm{n}_{\mathrm{B}} \mathrm{RT}} \\
& \frac{\mathrm{n}_{\mathrm{A}}}{\mathrm{n}_{\mathrm{B}}}=\frac{2}{3}=\frac{\frac{\mathrm{m}_{\mathrm{A}}}{\mathrm{m}_{\mathrm{B}}}}{\frac{\mathrm{m}_{\mathrm{B}}}{\mathrm{m}}}=\frac{2}{3} \\
& \frac{\mathrm{m}_{\mathrm{A}}}{\mathrm{m}_{\mathrm{B}}}=\frac{2}{3} \\
& \Rightarrow 3 \mathrm{~m}_{\mathrm{A}}=2 \mathrm{~m}_{\mathrm{B}} \\
&
\end{aligned}

For adiabatic process
$\mathrm{TV}^{\gamma-1}=$ constant

\begin{aligned}
& \Rightarrow \quad \mathrm{T}_1 \mathrm{~V}_1^{\gamma-1}=\mathrm{T}_2 \mathrm{~V}_2^{\gamma-1} \Rightarrow \frac{\mathrm{T}_1}{\mathrm{~T}_2}=\left(\frac{\mathrm{V}_2}{\mathrm{~V}_1}\right)^{\gamma-1} \\
& \Rightarrow \quad \frac{2 \mathrm{~T}}{\mathrm{~T}^{\prime}}=2^{\gamma-1} \Rightarrow 2^{\prime}=2^{\gamma-1} \Rightarrow 1=\gamma-1 \Rightarrow \gamma=2
\end{aligned}

Work done in isobaric process is given as

\begin{aligned}
& \Delta \mathrm{W}=\Delta \mathrm{Q}-\Delta \mathrm{U} \\
& =\mathrm{nC}_{\mathrm{p}} \Delta \mathrm{T}-\mathrm{nC}_{\mathrm{V}} \Delta \mathrm{T} \\
& =\mathrm{nC}_{\mathrm{P}} \Delta \mathrm{T}\left(1-\frac{1}{\gamma}\right) \\
& =\Delta \mathrm{Q}\left(1-\frac{1}{\gamma}\right) \\
& =700\left(1-\frac{5}{7}\right)=200 \mathrm{~J}
\end{aligned}

For adiabatically process

\begin{array}{ll}
\mathrm{T}_1 \mathrm{~V}_1^{\gamma-1}=\mathrm{T}_2 \mathrm{~V}_2^{\gamma-1} & \\
\mathrm{TV}^{\gamma-1}=\frac{\mathrm{T}}{2}(4 \mathrm{~V})^{\gamma-1} & \\
2=(2)^{2 \gamma-2} & \gamma=\frac{3}{2} \\
2 \gamma-2=1 &
\end{array}

Work done by the gas

\begin{aligned}
& \mathrm{W}=\frac{\mathrm{nR}\left(\mathrm{T}_2-\mathrm{T}_1\right)}{\gamma-1}=\frac{\mathrm{nR}\left(\mathrm{T}-\frac{\mathrm{T}}{2}\right)}{\frac{3}{2}-1} \\
& =\frac{\mathrm{nR} \frac{\mathrm{T}}{2}}{1 / 2} \\
& =\mathrm{nRT}=\text { PV So, } \alpha=1
\end{aligned}

We know that, adiabatic relation,

p V^\gamma=\text { constant }

For adiabatic process $A \rightarrow B$
\begin{aligned}
2 p_0 V_0^\gamma & =p_0 V_1^\gamma \\
\Rightarrow \quad V_1^\gamma & =2 V_0^\gamma \Rightarrow V_1=2^{1 / \gamma} V_0
\end{aligned}
